import React from 'react';

const SuccessMessage = ({ formData }) => {
  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-teal-100 flex items-center justify-center p-6">
      <div className="bg-white shadow-lg rounded-xl p-8 w-full max-w-md">
        <div className="text-center">
          <h2 className="text-4xl font-bold text-teal-600 mb-6 animate__animated animate__fadeIn">Quiz Created Successfully!</h2>
          <h4 className="text-xl text-gray-700 mb-6">Here are the quiz details:</h4>
        </div>

        <div className="space-y-4 text-lg text-gray-700">
          <p><strong>Name:</strong> <span className="text-teal-500 font-medium">{formData.name}</span></p>
          <p><strong>Exam:</strong> {formData.exam}</p>
          <p><strong>Difficulty Levels:</strong> {formData.difficultyLevels.join(', ')}</p>
          <p><strong>Class / Year:</strong> {formData.classYear}</p>
          <p><strong>Subjects:</strong> {formData.subjects.join(', ')}</p>
          <p><strong>Topics:</strong> {formData.topics.join(', ')}</p>
          <p><strong>Quiz Mode:</strong> {formData.quizMode}</p>
          <p><strong>Number of Questions:</strong> {formData.numberOfQuestions}</p>

          {formData.addHints && <p><strong>Hints:</strong> <span className="text-teal-500">Enabled</span></p>}
          {formData.answerExplanation && <p><strong>Answer Explanation:</strong> <span className="text-teal-500">Enabled</span></p>}
          {formData.breakIntoSubtopics && <p><strong>Break Into Subtopics:</strong> <span className="text-teal-500">Enabled</span></p>}
        </div>

        <div className="mt-8 text-center">
          <button
            className="bg-teal-500 text-white text-lg py-3 px-8 rounded-xl shadow-md hover:bg-teal-600 transition-colors"
            onClick={() => window.location.reload()}
          >
            Create Another Quiz
          </button>
        </div>
      </div>
    </div>
  );
};

export default SuccessMessage;
